# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["这轮原本想去核对「回测和线上是不是同一套规则」。","结果是：不是。而且我事先猜错了方向。","","=== 一、发现 ===","","tools/liveedge.py 是产出「这个策略能赚多少」头条数字的工具。它的规则是：","","    进  if C[i] > s and C[i-1] <= sp        # s 是裸 SMA","    出  elif C[i] < s","","而线上 TrendStrategy 是带滞回的两条线：","","    进  cl[-1] >  sma*(1+h)","    出  cl[-1] <= sma*(1-h)","","也就是说：量「真实边际」的工具，量的不是线上那套规则的边际。","","=== 二、量化（13200 根 4h，2020-10~2026-10，双边 0.10%）===","","    滞回带      总收益    CAGR     回撤    笔数   累计手续费","    0%（旧口径） +472%   +33.6%   47.8%   181    120.0%","    0.1%        +542%   +36.2%   46.1%   147    103.5%","    0.2%（线上） +548%   +36.4%   46.1%   126     87.9%","    0.5%        +573%   +37.2%   44.3%   101     76.1%","    1%          +578%   +37.4%   40.8%    76     59.4%","    2%          +526%   +35.6%   43.1%    50     35.9%","","=== 三、我猜错了方向 ===","","动手前我的判断是：滞回带让买点更晚更高、卖点更晚更低，对只做多应该【有害】。","所以我会预期 0.2% 比 0% 差。","","数据是反的：0.2% 比 0% 好 +76 个百分点，笔数少 55 笔。","原因是带子过滤掉擦边的假突破，省下的手续费是 32 个百分点的权益","（120.0% -> 87.9%）。在 6 年里，手续费才是主要的摩擦。","","所以这不是「线上比回测差」，而是「工具长期低估了策略」。","结论方向反了，但缺陷是真的：工具跑的确实不是线上规则。","","=== 四、修法：让它不可能再走散 ===","","1) 带子从真实配置导入（TradingCfg().trend_hysteresis_pct），工具里不许再写字面量。","2) 把循环抽成 simulate()，这样才可能做【行为级】对照。","3) tests/test_liveedge_parity.py：同一份收盘序列，","   一边只由 TrendStrategy.state() 驱动，一边由 liveedge.simulate() 驱动，","   进出发生在哪一根必须逐笔相同。","","=== 五、变异：8 条，两轮才全红 ===","","第一轮 8 条里有 2 条绿的：","  「进场 >= 而非 >」—— 随机浮点几乎不会恰好等于阈值，序列里没有相等样本","  「进场比上上根」—— 那份数据上两种取法结果相同","","这两个都是真盲区，不是测试写得不好。补法是把边界【造出来】：","  - 前 201 根恒为 100，最后一根恰好放在进场线上 -> 测严格大于","  - 构造 上-下-上，钉住进场必须落在 i=203 -> 测比的是上一根","","补边界时我又错了一次：用 100*(1-h) 当出场线，","但那时 SMA 窗口已经把先前进场的高价算进去了，价格压根没落在线上，","缺陷照样漏过去。正确做法是先算窗口、得到真实出场线、再把价格精确放上去。","","最终 8 条全部变红。","","=== 六、更新后的诚实风险数字（同源口径）===","","    CAGR +36.4%  最大回撤 46.1%  Calmar 0.79  126 笔","    在场 51%  持仓期最大浮亏 11.6%（止损线 25%，从未触发）","    逐年：2020 +59.8 / 2021 +40.2 / 2022 -27.3 / 2023 +102.1 / 2024 +95.1","          2025 -8.4 / 2026 +10.1","    100U -> 648U（最坏 349U）；买入持有 603U（最坏 138U）","","=== 七、验证 ===","","全量 475 条全绿（469 -> 475）。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":94,"theme":"量真实边际的工具跑的不是线上规则：裸均线 vs 滞回带，差 76 个百分点","hypothesis_wrong":"我事先判断滞回带对只做多有害（买更高卖更低）；数据相反：0.2% 比 0% 好 +76pp","mechanism":"带子过滤擦边假突破，笔数 181->126，手续费 120.0% -> 87.9% 权益","table":{"0%":"+472% CAGR 33.6% DD 47.8% 181笔","0.2%":"+548% CAGR 36.4% DD 46.1% 126笔","1%":"+578% CAGR 37.4% DD 40.8% 76笔"},"fix":["带子从 TradingCfg 导入，不许字面量","循环抽成 simulate() 以便行为级对照","tests/test_liveedge_parity.py 逐笔对照"],"mutation_rounds":"第一轮 8 条中 2 条绿（>= 与 C[i-2]），补边界样本后 8/8 红","self_inflicted":"用 100*(1-h) 当出场线，但 SMA 窗口已含进场高价，价格没落在线上，缺陷漏过","honest_risk_updated":{"CAGR":"+36.4%","MDD":"46.1%","Calmar":0.79,"trades":126,"in_market":"51%","MAE":"11.6%"},"tests_total":475,"account_state":{"spot_usdt":0}}''')
